<?php
namespace Tests\Feature;
use App\Models\FuelType; use App\Models\User; use App\Models\Vehicle; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class Version110QualityTest extends TestCase { use RefreshDatabase;
 private function user(): User { return User::create(['name'=>'Supervisor','username'=>'quality'.uniqid(),'password'=>'SenhaLocal!12345','auth_source'=>'local','role'=>'supervisor','is_active'=>true]); }
 public function test_dashboard_shows_real_vehicle_availability_and_version_110_accessibility_markup(): void { $user=$this->user();$fuel=FuelType::create(['name'=>'Gasolina','abbreviation'=>'GAS','active'=>true]);foreach(['active'=>'ATV1101','maintenance'=>'MAN1101','inactive'=>'INA1101'] as $status=>$plate)Vehicle::create(['plate'=>$plate,'model'=>$status,'fuel_type_id'=>$fuel->id,'current_odometer'=>0,'status'=>$status,'maintenance_interval_km'=>10000,'maintenance_interval_days'=>180]);$this->actingAs($user,'ldap')->get('/')->assertOk()->assertSee('Disponibilidade da frota')->assertSee('Veículos em manutenção')->assertSee('Pular para o conteúdo principal')->assertSee('versão 1.10'); }
 public function test_manual_and_request_form_expose_version_110_usage_affordances(): void { $user=$this->user();$fuel=FuelType::create(['name'=>'Gasolina','abbreviation'=>'GAS','active'=>true]);Vehicle::create(['plate'=>'FRM1101','model'=>'Teste','fuel_type_id'=>$fuel->id,'current_odometer'=>0,'status'=>'active','maintenance_interval_km'=>10000,'maintenance_interval_days'=>180]);$this->actingAs($user,'ldap')->get('/manual-operacao')->assertOk()->assertSee('versão 1.10')->assertSee('Disponibilidade de veículos e filtros');$this->actingAs($user,'ldap')->get('/requisicoes/nova')->assertOk()->assertSee('class="form-grid"',false); }
}
